// Is a lat/lng inside the bake area (the three neighborhoods plus the context
// ring)? The poller drops every vehicle outside it before writing anything.
//
// bake-area.json is generated by scripts/bake-routes.ts from src/data/city.bin,
// with the projection constants of src/geo/projection.ts, so this matches the
// bake exactly; area.test.ts checks both against the originals.

import bakeArea from './bake-area.json' with { type: 'json' }

interface BakeArea {
  origin: { lat: number; lng: number }
  metersPerDegLat: number
  metersPerDegLng: number
  ringMeters: number
  rings: number[][] // [x0, z0, x1, z1, ...] in scene meters
}

const AREA = bakeArea as BakeArea
const R = AREA.ringMeters

let minX = Infinity
let minZ = Infinity
let maxX = -Infinity
let maxZ = -Infinity
for (const ring of AREA.rings)
  for (let i = 0; i < ring.length; i += 2) {
    minX = Math.min(minX, ring[i])
    maxX = Math.max(maxX, ring[i])
    minZ = Math.min(minZ, ring[i + 1])
    maxZ = Math.max(maxZ, ring[i + 1])
  }

export function toAreaMeters(lat: number, lng: number): [number, number] {
  return [(lng - AREA.origin.lng) * AREA.metersPerDegLng, -(lat - AREA.origin.lat) * AREA.metersPerDegLat]
}

function inRing(x: number, z: number, r: number[]): boolean {
  let inside = false
  for (let i = 0, j = r.length - 2; i < r.length; j = i, i += 2) {
    const xi = r[i]
    const zi = r[i + 1]
    const xj = r[j]
    const zj = r[j + 1]
    if (zi > z !== zj > z && x < ((xj - xi) * (z - zi)) / (zj - zi) + xi) inside = !inside
  }
  return inside
}

function distToRing(x: number, z: number, r: number[]): number {
  let d = Infinity
  for (let i = 0, j = r.length - 2; i < r.length; j = i, i += 2) {
    const ax = r[j]
    const az = r[j + 1]
    const dx = r[i] - ax
    const dz = r[i + 1] - az
    const len2 = dx * dx + dz * dz
    const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, ((x - ax) * dx + (z - az) * dz) / len2))
    d = Math.min(d, Math.hypot(x - (ax + t * dx), z - (az + t * dz)))
  }
  return d
}

export function inBakeArea(lat: number, lng: number): boolean {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return false
  const [x, z] = toAreaMeters(lat, lng)
  if (x < minX - R || x > maxX + R || z < minZ - R || z > maxZ + R) return false
  return AREA.rings.some((r) => inRing(x, z, r)) || AREA.rings.some((r) => distToRing(x, z, r) <= R)
}
